code_state.current_implementation:

export class LocalFSAdapter {
  private directoryHandle: FileSystemDirectoryHandle | null = null;
  private projectId: string | null = null;

  async selectDirectory(): Promise<FileSystemDirectoryHandle | null> {
    try {
      const handle = await window.showDirectoryPicker();
      this.directoryHandle = handle;
      this.projectId = crypto.randomUUID();
      return handle;
    } catch (error) {
      if (isPermissionDeniedError(error)) {
        console.warn('Directory access denied');
      }
      return null;
    }
  }

  async getDirectoryHandle(): Promise<FileSystemDirectoryHandle | null> {
    return this.directoryHandle;
  }

  async hasPermission(): Promise<boolean> {
    if (!this.directoryHandle) return false;
    const status = await this.directoryHandle.queryPermission({ mode: 'readwrite' });
    return status === 'granted';
  }

  async requestPermission(): Promise<boolean> {
    if (!this.directoryHandle) return false;
    const status = await this.directoryHandle.requestPermission({ mode: 'readwrite' });
    return status === 'granted';
  }

  async readFile(fileName: string): Promise<string | null> {
    // Implementation reads from handle...
  }

  async writeFile(fileName: string, content: string): Promise<boolean> {
    // Implementation writes to handle...
  }
}

code_state.schema_definition:

// Epic 24: Performance & UX Optimization tables
fsaHandles!: Table<FSAHandleRecord, string>;

this.version(11).stores({
  fsaHandles: 'projectId, directoryPath'
});

// FSAHandleRecord type
interface FSAHandleRecord {
  projectId: string;
  directoryPath: string;
  kind: 'directory';
  name: string;
  permissionStatus: 'granted' | 'prompt' | 'denied' | 'unknown';
  grantedAt?: number;
  lastAccessedAt?: number;
}

code_state.helper_functions:

async function storeFSAHandle(handle: FSAHandleRecord): Promise<void> {
  await db.fsaHandles.put({
    ...handle,
    lastAccessedAt: Date.now()
  });
}

async function getFSAHandle(projectId: string): Promise<FSAHandleRecord | undefined> {
  return db.fsaHandles.get(projectId);
}

async function deleteFSAHandle(projectId: string): Promise<void> {
  await db.fsaHandles.delete(projectId);
}

async function updateFSAHandlePermission(
  projectId: string,
  status: FSAHandleRecord['permissionStatus']
): Promise<void> {
  await db.fsaHandles.update(projectId, {
    permissionStatus: status,
    ...(status === 'granted' ? { grantedAt: Date.now() } : {})
  });
}

async function clearAllFSAHandles(): Promise<void> {
  await db.fsaHandles.clear();
}

hint.pattern:

async persistHandle(handle: FileSystemDirectoryHandle, projectId: string) {
  const record: FSAHandleRecord = {
    projectId,
    kind: handle.kind,
    name: handle.name,
    directoryPath: await getPathFromHandle(handle), // if available
    permissionStatus: 'granted',
    grantedAt: Date.now(),
    lastAccessedAt: Date.now()
  };
  await storeFSAHandle(record);
}


async restoreHandle(projectId: string): Promise<FileSystemDirectoryHandle | null> {
  const record = await getFSAHandle(projectId);
  if (!record || record.permissionStatus !== 'granted') {
    return null;
  }

  try {
    // Try browser's handle persistence by ID
    const handle = await window.showDirectoryPicker({ id: projectId });
    return handle;
  } catch {
    // Silent re-grant failed
    await deleteFSAHandle(projectId);
    return null;
  }
}
